//! Hit-level acceptance: source roles follow exact numeric events, never names.
use mabi_meter_core::{capture_file::Input,combat::Stamp,hit_source::{HitSource,MAX_CELLS},protocol,replay::Replay,transport::{Flow,Segment}};
fn put(p:&mut[u8],at:usize,n:u64){p[at..at+8].copy_from_slice(&n.to_le_bytes());}
struct Fixture{r:Replay,seq:u32,time:u64}
impl Fixture{
    fn new()->Self{let mut r=Replay::new(true);r.live_scope=true;for a in [101,202,303]{let k=r.meter.registry.observe(0,1,a).unwrap();r.meter.registry.records.get_mut(&k).unwrap().kind=Some("player");}Self{r,seq:1,time:0}}
    fn feed(&mut self,w:i32,p:Vec<u8>){let payload=protocol::encode_frame(w,&p);let n=payload.len()as u32;self.r.feed(Input::Segment(Segment{timestamp_ns:self.time,flow:Flow{src:"192.0.2.1".into(),dst:"192.0.2.2".into(),sport:16000,dport:2345},seq:self.seq,payload,syn:false,fin:false,rst:false,ack:true})).unwrap();self.seq+=n;self.time+=1_000_000;}
    fn hp(&mut self,target:u64,n:u64){let mut p=vec![0;21];put(&mut p,0,target);p[8..12].copy_from_slice(&8u32.to_le_bytes());put(&mut p,12,n);self.feed(170205,p);}
    fn hit(&mut self,actor:u64,target:u64,skill:u32,flags:u8,extra:usize){let mut p=vec![0;35+extra];put(&mut p,0,actor);put(&mut p,8,target);p[16..20].copy_from_slice(&skill.to_le_bytes());p[24]=flags;self.feed(20526,p);}
    fn floater(&mut self,actor:u64,target:u64,amount:u64,aux:u64,flags:u8,extra:usize){let mut p=vec![0;53+extra];put(&mut p,0,actor);put(&mut p,8,target);put(&mut p,16,amount);put(&mut p,24,aux);p[32]=flags;self.feed(21196,p);}
    fn prepared(skill:u32)->Self{let mut f=Self::new();f.hp(999,1000);f.hp(999,900);f.hit(202,999,skill,7,0);f}
    fn done(mut self,actor:u32,bound:u64){self.r.finish();assert_eq!(self.r.meter.raw_hits.len(),1);assert_eq!(self.r.meter.raw_hits[0].source.actor,actor);assert_eq!(self.r.hit_source.audit()["bound"],bound);assert_eq!(self.r.health.attribution.audit()["invariant"],true);assert_eq!(self.r.numeric.detected,self.r.health.loss);assert_eq!(self.r.health.loss,self.r.health.explicit+self.r.health.allocated+self.r.health.unassigned);}
}
#[test]fn exact_hit_binding_preserves_wire_actor_amount_flags_and_receipt_identity(){let mut f=Fixture::prepared(77);f.floater(101,999,100,0,7,0);f.r.finish();assert_eq!(f.r.meter.raw_hits[0].source.actor,202);assert_eq!(f.r.meter.raw_hits[0].damage.amount,100);assert_eq!(f.r.meter.session.total.damage,100);assert_eq!(f.r.meter.snapshot().display_hits,1);assert_eq!(f.r.health.allocated,0);assert_eq!(f.r.combat.damage_model.anchors,0);assert_eq!(f.r.audit()["damage_wire_fields"]["records"][0]["source_prefix"],101);assert_eq!(f.r.audit()["hit_source_binding"]["records"][0]["wire_actor"]["actor"],101);f.r.retry_pending_credits().unwrap();f.r.retry_pending_credits().unwrap();assert_eq!(f.r.meter.raw_hits.len(),1);}
#[test]fn arbitrary_and_unknown_skill_keys_use_the_same_hit_rule(){for skill in [0,1,77,883,4_000_000_000]{let mut f=Fixture::prepared(skill);f.floater(101,999,100,0,7,0);f.done(202,1);}}
#[test]fn friendly_healing_hit_cannot_claim_another_targets_damage_or_establish_activity(){let mut f=Fixture::new();let main=f.r.meter.registry.current_key(0,1,202).unwrap();f.r.meter.registry.assign(Some(main)).unwrap();f.hp(999,1000);f.hp(101,400);f.hp(999,900);f.hp(101,500);f.hit(202,101,77,7,0);f.floater(101,999,100,0,7,0);f.r.finish();assert_eq!(f.r.hit_source.audit()["bound"],0);assert_eq!(f.r.meter.raw_hits[0].source.actor,101);assert!(f.r.meter.last_self_activity.is_none());assert_eq!(f.r.health.allocated,0);assert_eq!(f.r.health.unassigned,0);}
#[test]fn one_skill_can_have_friendly_and_hostile_hits_without_a_skill_ban(){let mut f=Fixture::new();f.hp(101,400);f.hp(101,500);f.hit(202,101,77,7,0);f.hp(999,1000);f.hp(999,900);f.hit(202,999,77,7,0);f.floater(101,999,100,0,7,0);f.done(202,1);}
#[test]fn unchanged_or_rising_hp_is_not_a_damaging_hit_binding(){for next in [1000,1100]{let mut f=Fixture::new();f.hp(999,1000);f.hp(999,next);f.hit(202,999,77,7,0);f.floater(101,999,100,0,7,0);f.done(101,0);}}
#[test]fn the_actual_hit_amount_is_required_not_just_source_flags_or_skill(){let mut f=Fixture::prepared(77);f.floater(101,999,99,0,7,0);f.done(101,0);}
#[test]fn zero_impact_floater_is_not_a_positive_source_binding(){let mut f=Fixture::prepared(77);f.floater(101,999,100,100,7,0);f.done(101,0);}
#[test]fn identical_flags_on_a_different_target_do_not_bind(){let mut f=Fixture::new();f.hp(999,1000);f.hp(999,900);f.hit(202,998,77,7,0);f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn different_hit_flags_do_not_bind(){let mut f=Fixture::prepared(77);f.floater(101,999,100,0,8,0);f.done(101,0);}
#[test]fn multiple_presentations_leave_source_ambiguous(){let mut f=Fixture::prepared(77);f.hit(303,999,77,7,0);f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn extended_packet_layouts_are_not_promoted(){for kind in [0,1]{let mut f=Fixture::new();f.hp(999,1000);f.hp(999,900);f.hit(202,999,77,7,usize::from(kind==0));f.floater(101,999,100,0,7,usize::from(kind==1));f.done(101,0);}}
#[test]fn intervening_target_hp_update_ends_the_hit_cell(){let mut f=Fixture::prepared(77);f.hp(999,850);f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn intervening_hp_sentinel_cannot_leave_a_stale_hit_source_binding(){let mut f=Fixture::prepared(77);f.hp(999,i64::MAX as u64);f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn hit_must_immediately_follow_target_hp_in_directional_order(){let mut f=Fixture::new();f.hp(999,1000);f.hp(999,900);f.feed(20000,vec![]);f.hit(202,999,77,7,0);f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn locality_is_measured_at_capture_time(){let mut f=Fixture::prepared(77);f.time+=100_000_001;f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn later_presentation_cannot_rewrite_an_earlier_floater(){let mut f=Fixture::new();f.hp(999,1000);f.hp(999,900);f.floater(101,999,100,0,7,0);f.hit(202,999,77,7,0);f.done(101,0);}
#[test]fn unknown_or_conflicting_identity_cannot_confer_a_new_source(){for conflict in [false,true]{let mut f=Fixture::prepared(77);let k=f.r.meter.registry.current_key(0,1,202).unwrap();let m=f.r.meter.registry.records.get_mut(&k).unwrap();if conflict{m.conflicting=true;}else{m.kind=Some("npc");}f.floater(101,999,100,0,7,0);f.done(101,0);}}
#[test]fn transport_loss_clears_hit_binding_without_dropping_damage(){let mut f=Fixture::prepared(77);f.r.feed(Input::Loss{code:"synthetic loss".into(),reset:false}).unwrap();f.floater(101,999,100,0,7,0);f.done(101,0);}
#[test]fn self_selection_does_not_change_hit_eligibility_or_credit(){for actor in [None,Some(101),Some(202)]{let mut f=Fixture::prepared(77);let k=actor.and_then(|a|f.r.meter.registry.current_key(0,1,a));f.r.meter.registry.assign(k).unwrap();f.floater(101,999,100,0,7,0);f.done(202,1);}}
#[test]fn cache_pressure_bounds_memory_and_only_removes_binding_coverage(){let mut b=HitSource::default();for n in 1..MAX_CELLS+20{let target=mabi_meter_core::identity::EntityKey{process:0,binding:1,actor:n as u32,generation:1};let before=Stamp{process:0,context:1,continuity:0,frame:1,order:1,timestamp_ns:1,tcp_byte:0};let after=Stamp{frame:2,order:2,timestamp_ns:2,..before};b.hp(target,90,after,Some((before,100)));}assert_eq!(b.audit()["cells"],MAX_CELLS);assert!(b.owned_bytes()<=HitSource::ceiling_bytes());b.clear();assert_eq!(b.audit()["cells"],0);}
